1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioOutcome = {
6	  results: QuoteResult[];
7	};
8	
9	type Item = { type: string; cursed?: boolean; enchantment?: number };
10	
11	type Customer = { yearsWithMHPCO: number };
12	
13	/** The policy-scope context a quote is priced in: who is buying, and whether
14	 * this is their first contract or a follow-up. */
15	type Policy = { customer: Customer; isFollowUpContract: boolean };
16	
17	type Scenario = {
18	  customer: Customer;
19	  steps: { items: Item[] }[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	const CURSE_SURCHARGE = 0.5;
25	const HIGH_ENCHANTMENT_THRESHOLD = 5;
26	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
27	const LOYALTY_THRESHOLD_YEARS = 2;
28	const LOYALTY_DISCOUNT = 0.2;
29	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
30	
31	const BASE_PREMIUMS: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const ALIKE_BLOCK_SIZE = 3;
41	const ALIKE_BLOCK_PREMIUM = 60;
42	
43	type AlikeGroup = [type: string, count: number];
44	
45	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
46	  const countByType = new Map<string, number>();
47	
48	  for (const item of items) {
49	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
50	  }
51	
52	  return [...countByType];
53	};
54	
55	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
56	
57	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
58	
59	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
60	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
61	
62	  return count * basePremiumOfType(type);
63	};
64	
65	/**
66	 * The policy base premium: the sum of the item base premiums, with the
67	 * alike-block discount applied. Policy-scope modifiers are percentages OF
68	 * THIS amount — never of a total that already includes item surcharges.
69	 */
70	const policyBasePremiumOf = (items: Item[]): number =>
71	  groupAlikeItems(items)
72	    .map(basePremiumOfGroup)
73	    .reduce((total, groupPremium) => total + groupPremium, 0);
74	
75	/**
76	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
77	 * premium, independent of the policy base and of the alike-block discount.
78	 */
79	const isCursed = (item: Item): boolean => item.cursed === true;
80	
81	const isHighlyEnchanted = (item: Item): boolean =>
82	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
83	
84	const itemSurchargeRateOf = (item: Item): number =>
85	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
86	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
87	
88	const itemSurchargesOf = (items: Item[]): number =>
89	  items.reduce(
90	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
91	    0,
92	  );
93	
94	/**
95	 * Policy-scope modifiers: each is a percentage of the policy base premium.
96	 * Surcharges and discounts are netted into a single rate, so the policy base is
97	 * multiplied exactly once — this keeps the result free of the rounding drift
98	 * that separate discount and surcharge terms would introduce. The netted rate
99	 * (and hence the returned amount) is negative when the discounts outweigh the
100	 * surcharges.
101	 */
102	const isLongStanding = (customer: Customer): boolean =>
103	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
104	
105	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
106	  FIRST_INSURANCE_SURCHARGE -
107	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
108	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
109	
110	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
111	  policyBase * policyModifierRateOf(policy);
112	
113	const quotePremium = (items: Item[], policy: Policy): number => {
114	  const policyBase = policyBasePremiumOf(items);
115	  const premium =
116	    policyBase +
117	    itemSurchargesOf(items) +
118	    policyModifiersOn(policyBase, policy) +
119	    PROCESSING_FEE;
120	
121	  return Math.ceil(premium);
122	};
123	
124	/**
125	 * A step is a follow-up contract when the customer already holds one, i.e. when
126	 * an earlier step in the scenario has issued a quote.
127	 *
128	 * KNOWN SIMPLIFICATION: this counts *any* earlier step, not just earlier
129	 * quotes, because every step is currently a quote. Once claim steps exist, a
130	 * claim at index 0 would wrongly make the quote at index 1 a follow-up; this
131	 * must then count preceding QUOTE steps only. No test covers it yet.
132	 */
133	const isFollowUpContractAt = (stepIndex: number): boolean => stepIndex > 0;
134	
135	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
136	  results: scenario.steps.map((step, stepIndex) => ({
137	    premium: quotePremium(step.items, {
138	      customer: scenario.customer,
139	      isFollowUpContract: isFollowUpContractAt(stepIndex),
140	    }),
141	  })),
142	});
