/**
 * The quotes issued before a given step. A quote is a follow-up contract when
 * the customer already holds one, so this count — not the step index — is what
 * decides the follow-up discount.
 *
 * Every step is currently a quote, so this equals the step index. It stops
 * being the step index as soon as claim steps exist, which is exactly why the
 * caller must ask this question rather than read the index.
 */
const quotesIssuedBefore = (steps: readonly { items: Item[] }[]): number =>
  steps.length;

export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step, stepIndex) => ({
    premium: quotePremium(step.items, {
      customer: scenario.customer,
      isFollowUpContract:
        quotesIssuedBefore(scenario.steps.slice(0, stepIndex)) > 0,
    }),
  })),
});

